/**
 * Regenerates src/vendor/chart-bundle.js from the official chart.js npm package.
 *
 * This is the Chart constructor the library's own charts import, via
 * src/ui/components/ChartWrapper.js. It is distinct from chart-source.js, which
 * is the UMD build wrapped as a string for injection into the GitHub Pages
 * report — that one is written by dev/generate-chart-vendor.js.
 *
 * The bundle's header used to name that other script as its generator, which
 * meant the largest chart file in the package had no command that reproduced
 * it. An AMO reviewer is entitled to rebuild every generated file from the
 * documented steps, so this exists to be that command.
 *
 * Not minified, unlike the vis-network bundle: chart.js ships readable ESM and
 * keeping it readable costs about 200KB of a file a reviewer may well want to
 * read.
 *
 * Usage: node dev/generate-chart-bundle.js   (npm run vendor:chart)
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import esbuild from "esbuild";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");

function readLockVersion(pkg) {
  try {
    const lock = JSON.parse(fs.readFileSync(path.join(ROOT, "package-lock.json"), "utf8"));
    return lock.packages?.[`node_modules/${pkg}`]?.version || "unknown";
  } catch {
    return "unknown";
  }
}

const chartVer = readLockVersion("chart.js");

// The entry is committed rather than written to a temp file, because it is the
// one part of this bundle that is ours: it picks chart.js/auto, which is what
// registers the controllers and scales the charts use.
const entry = path.join(ROOT, "src/vendor/chart-entry.js");
const outFile = path.join(ROOT, "src/vendor/chart-bundle.js");

esbuild.buildSync({
  entryPoints: [entry],
  bundle: true,
  format: "esm",
  platform: "browser",
  target: "es2020",
  minify: false,
  legalComments: "inline",
  outfile: outFile,
  absWorkingDir: ROOT,
});

const bundleContent = fs.readFileSync(outFile, "utf8");
const header =
  `// AUTO-GENERATED by dev/generate-chart-bundle.js — do not edit manually\n` +
  `// Source (official npm release, no CDN):\n` +
  `//   chart.js@${chartVer} + @kurkle/color (its only dependency)\n` +
  `//   https://www.npmjs.com/package/chart.js/v/${chartVer} (MIT License)\n` +
  `// Entry point: src/vendor/chart-entry.js\n` +
  `// Bundled with esbuild, not minified.\n\n`;
fs.writeFileSync(outFile, header + bundleContent);

const kb = (fs.statSync(outFile).size / 1024).toFixed(0);
console.log(`✓ vendor/chart-bundle.js → chart.js@${chartVer} (${kb}KB)`);
